#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU.
# Every SKU in movements.log gets a line (even with a zero net), and every
# catalog SKU gets a line, including SKUs with no movements that day (e.g. SKU-9).
awk '{ net[$1] += ($2 == "receipt" ? $3 : -$3); seen[$1] = 1 }
     BEGIN { net["SKU-9"] += 0; seen["SKU-9"] = 1 }
     END { for (sku in seen) print sku, net[sku] }' \
    movements.log | sort > stock.txt

#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU
# that appears in movements.log, plus every catalog SKU (SKU-9), even if it
# has no movements that day.
awk 'NR == FNR { if ($1 ~ /^SKU-9$/) cat = 1; next }
     { net[$1] += ($2 == "receipt" ? $3 : -$3); seen[$1] = 1 }
     END {
         for (sku in seen) print sku, net[sku]
         if (cat) print "SKU-9", (SKU-9 in net ? net["SKU-9"] : 0)
     }' catalog.txt movements.log | sort > stock.txt

#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU
# that appears in movements.log, plus every catalog SKU (e.g. SKU-9), even if
# it has no movements that day.
awk '{ net[$1] += ($2 == "receipt" ? $3 : -$3); seen[$1] = 1 }
     BEGIN { seen["SKU-9"] = 1 }
     END { for (sku in seen) print sku, net[sku] }' \
    movements.log | sort > stock.txt
